// Helper functions for tooltip and popover styling
func getTooltipData(trigger string, delay int) string {
	delayStr := "0"
	if delay > 0 {
		delayStr = strconv.Itoa(delay)
	}

	return `{
		show: false,
		timer: null,
		showTooltip() {
			if (this.timer) clearTimeout(this.timer);
			this.timer = setTimeout(() => {
				this.show = true;
			}, ` + delayStr + `);
		},
		hideTooltip() {
			if (this.timer) clearTimeout(this.timer);
			this.show = false;
		},
		toggleTooltip() {
			this.show = !this.show;
		}
	}`
}

func getPopoverData(trigger string, dismissible bool) string {
	return `{
		show: false,
		showPopover() {
			this.show = true;
		},
		hidePopover() {
			this.show = false;
		},
		togglePopover() {
			this.show = !this.show;
		}
	}`
}

